// Straight-line kernels of seven operations of rigid(3), the arithmetic of
// each written out by hand, for the benchmarks to time the library against.
// Generated by test/reference/reference_kernels.py, which derives each term
// from the definitions by a route that shares no code with the library; do
// not edit. To regenerate, from the repository's root:
//   python3 -I test/reference/reference_kernels.py
//       > test/bench/reference_kernels.hpp
//
// Layouts, as the rga3 preset stores them: a point on e1 e2 e3 e4, a line on
// e41 e42 e43 e23 e31 e12, a plane on e423 e431 e412 e321, and a motor on
// e41 e42 e43 e1234 e23 e31 e12 1, where e41 = -e14, e31 = -e13, and
// e321 = -e123. Within an output the terms come in order of the first
// operand's coefficient, then the second's.
//
// The generator lays out one term list per line, so clang-format is off.
// clang-format off
#ifndef GALOOT_TEST_BENCH_REFERENCE_KERNELS_HPP
#define GALOOT_TEST_BENCH_REFERENCE_KERNELS_HPP

#include <array>

namespace reference_kernels {

// x ^ y, the line through two points, on e41 e42 e43 e23 e31 e12.
template <class T>
constexpr std::array<T, 6> wedge_point_point(
    const std::array<T, 4>& x,
    const std::array<T, 4>& y) {
  return {
      -(x[0] * y[3]) + x[3] * y[0], // e41
      -(x[1] * y[3]) + x[3] * y[1], // e42
      -(x[2] * y[3]) + x[3] * y[2], // e43
      x[1] * y[2] - x[2] * y[1], // e23
      -(x[0] * y[2]) + x[2] * y[0], // e31
      x[0] * y[1] - x[1] * y[0], // e12
  };
}

// p ^ q ^ r, the plane through three points, on e423 e431 e412 e321:
// first p ^ q on the bivectors e12 e13 e14 e23 e24 e34, then that
// join with r.
template <class T>
constexpr std::array<T, 4> wedge_point_point_point(
    const std::array<T, 4>& p,
    const std::array<T, 4>& q,
    const std::array<T, 4>& r) {
  const T e12 = p[0] * q[1] - p[1] * q[0];
  const T e13 = p[0] * q[2] - p[2] * q[0];
  const T e14 = p[0] * q[3] - p[3] * q[0];
  const T e23 = p[1] * q[2] - p[2] * q[1];
  const T e24 = p[1] * q[3] - p[3] * q[1];
  const T e34 = p[2] * q[3] - p[3] * q[2];
  return {
      e23 * r[3] - e24 * r[2] + e34 * r[1], // e423
      -(e13 * r[3]) + e14 * r[2] - e34 * r[0], // e431
      e12 * r[3] - e14 * r[1] + e24 * r[0], // e412
      -(e12 * r[2]) + e13 * r[1] - e23 * r[0], // e321
  };
}

// x v y, the point where a line meets a plane, on e1 e2 e3 e4.
template <class T>
constexpr std::array<T, 4> antiwedge_line_plane(
    const std::array<T, 6>& x,
    const std::array<T, 4>& y) {
  return {
      x[0] * y[3] + x[4] * y[2] - x[5] * y[1], // e1
      x[1] * y[3] - x[3] * y[2] + x[5] * y[0], // e2
      x[2] * y[3] + x[3] * y[1] - x[4] * y[0], // e3
      -(x[0] * y[0]) - x[1] * y[1] - x[2] * y[2], // e4
  };
}

// transform(x, Q) for a point x, Q v x v antireverse(Q), on x's
// layout e1 e2 e3 e4: first Q v x on the blades the
// second stage reads, then that times Q with antireverse's signs.
template <class T>
constexpr std::array<T, 4> transform_point(
    const std::array<T, 4>& x,
    const std::array<T, 8>& q) {
  const T e1 = q[1] * x[2] - q[2] * x[1] + q[3] * x[0] + q[4] * x[3];
  const T e2 = -(q[0] * x[2]) + q[2] * x[0] + q[3] * x[1] + q[5] * x[3];
  const T e3 = q[0] * x[1] - q[1] * x[0] + q[3] * x[2] + q[6] * x[3];
  const T e4 = q[3] * x[3];
  const T e123 = q[0] * x[0] + q[1] * x[1] + q[2] * x[2] - q[7] * x[3];
  const T e124 = q[2] * x[3];
  const T e134 = -(q[1] * x[3]);
  const T e234 = q[0] * x[3];
  return {
      e1 * q[3] - e2 * q[2] + e3 * q[1] + e4 * q[4] + e123 * q[0] - e124 * q[5] - e134 * q[6] - e234 * q[7], // e1
      e1 * q[2] + e2 * q[3] - e3 * q[0] + e4 * q[5] + e123 * q[1] + e124 * q[4] + e134 * q[7] - e234 * q[6], // e2
      -(e1 * q[1]) + e2 * q[0] + e3 * q[3] + e4 * q[6] + e123 * q[2] - e124 * q[7] + e134 * q[4] + e234 * q[5], // e3
      e4 * q[3] + e124 * q[2] - e134 * q[1] + e234 * q[0], // e4
  };
}

// transform(x, Q) for a line x, Q v x v antireverse(Q), on x's
// layout e41 e42 e43 e23 e31 e12: first Q v x on the blades the
// second stage reads, then that times Q with antireverse's signs.
template <class T>
constexpr std::array<T, 6> transform_line(
    const std::array<T, 6>& x,
    const std::array<T, 8>& q) {
  const T scalar = -(q[0] * x[3]) - q[1] * x[4] - q[2] * x[5] - q[4] * x[0] - q[5] * x[1] - q[6] * x[2];
  const T e12 = q[0] * x[4] - q[1] * x[3] + q[3] * x[5] + q[4] * x[1] - q[5] * x[0] + q[7] * x[2];
  const T e13 = q[0] * x[5] - q[2] * x[3] - q[3] * x[4] + q[4] * x[2] - q[6] * x[0] - q[7] * x[1];
  const T e14 = -(q[1] * x[2]) + q[2] * x[1] - q[3] * x[0];
  const T e23 = q[1] * x[5] - q[2] * x[4] + q[3] * x[3] + q[5] * x[2] - q[6] * x[1] + q[7] * x[0];
  const T e24 = q[0] * x[2] - q[2] * x[0] - q[3] * x[1];
  const T e34 = -(q[0] * x[1]) + q[1] * x[0] - q[3] * x[2];
  const T e1234 = -(q[0] * x[0]) - q[1] * x[1] - q[2] * x[2];
  return {
      -(e14 * q[3]) + e24 * q[2] - e34 * q[1] - e1234 * q[0], // e41
      -(e14 * q[2]) - e24 * q[3] + e34 * q[0] - e1234 * q[1], // e42
      e14 * q[1] - e24 * q[0] - e34 * q[3] - e1234 * q[2], // e43
      -(scalar * q[0]) + e12 * q[1] + e13 * q[2] - e14 * q[7] + e23 * q[3] + e24 * q[6] - e34 * q[5] - e1234 * q[4], // e23
      -(scalar * q[1]) - e12 * q[0] - e13 * q[3] - e14 * q[6] + e23 * q[2] - e24 * q[7] + e34 * q[4] - e1234 * q[5], // e31
      -(scalar * q[2]) + e12 * q[3] - e13 * q[0] + e14 * q[5] - e23 * q[1] - e24 * q[4] - e34 * q[7] - e1234 * q[6], // e12
  };
}

// transform(x, Q) for a plane x, Q v x v antireverse(Q), on x's
// layout e423 e431 e412 e321: first Q v x on the blades the
// second stage reads, then that times Q with antireverse's signs.
template <class T>
constexpr std::array<T, 4> transform_plane(
    const std::array<T, 4>& x,
    const std::array<T, 8>& q) {
  const T e1 = q[0] * x[3] + q[5] * x[2] - q[6] * x[1] + q[7] * x[0];
  const T e2 = q[1] * x[3] - q[4] * x[2] + q[6] * x[0] + q[7] * x[1];
  const T e3 = q[2] * x[3] + q[4] * x[1] - q[5] * x[0] + q[7] * x[2];
  const T e4 = -(q[0] * x[0]) - q[1] * x[1] - q[2] * x[2];
  const T e123 = -(q[3] * x[3]) + q[4] * x[0] + q[5] * x[1] + q[6] * x[2];
  const T e124 = q[0] * x[1] - q[1] * x[0] + q[3] * x[2];
  const T e134 = q[0] * x[2] - q[2] * x[0] - q[3] * x[1];
  const T e234 = q[1] * x[2] - q[2] * x[1] + q[3] * x[0];
  return {
      -(e4 * q[0]) + e124 * q[1] + e134 * q[2] + e234 * q[3], // e423
      -(e4 * q[1]) - e124 * q[0] - e134 * q[3] + e234 * q[2], // e431
      -(e4 * q[2]) + e124 * q[3] - e134 * q[0] - e234 * q[1], // e412
      e1 * q[0] + e2 * q[1] + e3 * q[2] - e4 * q[7] - e123 * q[3] - e124 * q[6] + e134 * q[5] - e234 * q[4], // e321
  };
}

// compose(x, y) = x v y, the motor that applies y and then x, on
// e41 e42 e43 e1234 e23 e31 e12 1.
template <class T>
constexpr std::array<T, 8> compose_motors(
    const std::array<T, 8>& x,
    const std::array<T, 8>& y) {
  return {
      x[0] * y[3] + x[1] * y[2] - x[2] * y[1] + x[3] * y[0], // e41
      -(x[0] * y[2]) + x[1] * y[3] + x[2] * y[0] + x[3] * y[1], // e42
      x[0] * y[1] - x[1] * y[0] + x[2] * y[3] + x[3] * y[2], // e43
      -(x[0] * y[0]) - x[1] * y[1] - x[2] * y[2] + x[3] * y[3], // e1234
      x[0] * y[7] + x[1] * y[6] - x[2] * y[5] + x[3] * y[4] + x[4] * y[3] + x[5] * y[2] - x[6] * y[1] + x[7] * y[0], // e23
      -(x[0] * y[6]) + x[1] * y[7] + x[2] * y[4] + x[3] * y[5] - x[4] * y[2] + x[5] * y[3] + x[6] * y[0] + x[7] * y[1], // e31
      x[0] * y[5] - x[1] * y[4] + x[2] * y[7] + x[3] * y[6] + x[4] * y[1] - x[5] * y[0] + x[6] * y[3] + x[7] * y[2], // e12
      -(x[0] * y[4]) - x[1] * y[5] - x[2] * y[6] + x[3] * y[7] - x[4] * y[0] - x[5] * y[1] - x[6] * y[2] + x[7] * y[3], // 1
  };
}

} // namespace reference_kernels

// clang-format on
#endif // GALOOT_TEST_BENCH_REFERENCE_KERNELS_HPP
